import { create } from 'zustand';
import { DEFAULT_MODELS, DEFAULT_PROVIDERS, LlmProvider, UserChatModel, encodeApiKey, getApiKey } from '../types/provider';
import { useNotificationStore } from './NotificationStore';

// ── Storage helpers ───────────────────────────────────────────────────────────

const STORAGE_KEY_PROVIDERS = 'athena_providers';
const STORAGE_KEY_MODELS = 'athena_models';
const STORAGE_KEY_SELECTED_MODEL = 'athena_selected_model';

function safeGetItem(key: string): string | null {
  try {
    return localStorage.getItem(key);
  } catch {
    return null;
  }
}

function safeSetItem(key: string, value: string): boolean {
  try {
    localStorage.setItem(key, value);
    return true;
  } catch {
    useNotificationStore.getState().addNotification('Storage is full — your latest changes were not saved.');
    return false;
  }
}

function safeRemoveItem(key: string): void {
  try {
    localStorage.removeItem(key);
  } catch {
    // non-critical
  }
}

function loadProviders(): LlmProvider[] {
  try {
    const raw = safeGetItem(STORAGE_KEY_PROVIDERS);
    if (raw) return JSON.parse(raw) as LlmProvider[];
  } catch {
    // corrupt storage
  }
  return [];
}

function loadModels(): UserChatModel[] {
  try {
    const raw = safeGetItem(STORAGE_KEY_MODELS);
    if (raw) return JSON.parse(raw) as UserChatModel[];
  } catch {
    // corrupt storage
  }
  return [];
}

function saveProviders(providers: LlmProvider[]): void {
  safeSetItem(STORAGE_KEY_PROVIDERS, JSON.stringify(providers));
}

function saveModels(models: UserChatModel[]): void {
  safeSetItem(STORAGE_KEY_MODELS, JSON.stringify(models));
}

function isLocalBaseUrl(baseUrl: string): boolean {
  const normalized = baseUrl.trim().toLowerCase();
  return normalized.includes('localhost') || normalized.includes('127.0.0.1') || normalized.includes('[::1]');
}

function providerCanBeUsedWithoutKey(provider: LlmProvider): boolean {
  return isLocalBaseUrl(provider.baseUrl);
}

function validateProvider(provider: LlmProvider): void {
  if (!provider.name.trim()) {
    throw new Error('Provider name is required.');
  }
  if (!provider.baseUrl.trim()) {
    throw new Error('Provider base URL is required.');
  }
  try {
    new URL(provider.baseUrl);
  } catch {
    throw new Error('Provider base URL is not a valid URL.');
  }
  // eslint-disable-next-line @typescript-eslint/no-unnecessary-condition -- explicit validation
  if (provider.messageFormat !== 'openai' && provider.messageFormat !== 'anthropic') {
    throw new Error('Provider message format must be "openai" or "anthropic".');
  }
}

// ── Seeding (first run) ───────────────────────────────────────────────────────


// ── Store ─────────────────────────────────────────────────────────────────────

interface ProviderState {
  providers: LlmProvider[];
  models: UserChatModel[];

  // Provider CRUD
  addProvider: (provider: LlmProvider) => void;
  updateProvider: (provider: LlmProvider) => void;
  deleteProvider: (providerId: string) => void;
  setProviderKey: (providerId: string, rawKey: string) => void;

  // Model CRUD
  addModel: (model: UserChatModel) => void;
  updateModel: (model: UserChatModel) => void;
  deleteModel: (modelId: string) => void;

  // Reset built-in provider to defaults
  resetProvider: (providerId: string) => void;

  // Selectors
  getProviderById: (id: string) => LlmProvider | undefined;
  getModelById: (id: string) => UserChatModel | undefined;
  getAvailableModels: () => UserChatModel[];
  getProviderForModel: (model: UserChatModel) => LlmProvider | undefined;
  hasAnyApiKey: () => boolean;
  /** True when a provider with a web-search-capable key (DeepSeek) is configured. */
  hasWebSearchProvider: () => boolean;
}

function initStore(): Pick<ProviderState, 'providers' | 'models'> {
  let providers = loadProviders();
  let models = loadModels();

  const hasStoredProviders = providers.length > 0;

  if (!hasStoredProviders) {
    // First run
    providers = DEFAULT_PROVIDERS.map((p) => ({ ...p, apiKeyEncrypted: '' }));
    models = DEFAULT_MODELS;
    saveProviders(providers);
    saveModels(models);
  } else {
    // Migration: Update built-in models with new defaults from DEFAULT_MODELS (e.g. forceTemperature)
    let modelsChanged = false;
    
    // Migration: DeepSeek V4
    const selected = safeGetItem(STORAGE_KEY_SELECTED_MODEL);
    if (selected === 'builtin-deepseek-chat') {
      safeSetItem(STORAGE_KEY_SELECTED_MODEL, 'builtin-deepseek-v4-flash');
    } else if (selected === 'builtin-deepseek-reasoner') {
      safeSetItem(STORAGE_KEY_SELECTED_MODEL, 'builtin-deepseek-v4-pro');
    } else if (selected === 'builtin-gemini-3-flash') {
      safeSetItem(STORAGE_KEY_SELECTED_MODEL, 'builtin-gemini-3-7-flash');
    } else if (selected === 'builtin-gpt-5-6-sol' || selected === 'builtin-gpt-5-6-terra') {
      safeSetItem(STORAGE_KEY_SELECTED_MODEL, 'builtin-gpt-6-1-sol');
    } else if (selected === 'builtin-gpt-5-6-luna') {
      safeSetItem(STORAGE_KEY_SELECTED_MODEL, 'builtin-gpt-6-luna');
    } else if (selected === 'builtin-kimi-k3') {
      safeSetItem(STORAGE_KEY_SELECTED_MODEL, 'builtin-kimi-k3-1-pro');
    }

    const existingModelIds = new Set(models.map((m) => m.id));

    // 1. Add missing built-in models
    for (const def of DEFAULT_MODELS) {
      if (!existingModelIds.has(def.id)) {
        models.push(def);
        modelsChanged = true;
      }
    }

    // 2. Update existing built-in models
    models = models.map((m) => {
      if (!m.isBuiltIn) return m;
      const def = DEFAULT_MODELS.find((dm) => dm.id === m.id);
      if (!def) return m;

      // Update specific properties that might have changed in code but need to persist in storage
      let updated = false;
      const next = { ...m };

      if (m.forceTemperature !== def.forceTemperature) {
        next.forceTemperature = def.forceTemperature;
        updated = true;
      }
      if (m.label !== def.label) {
        next.label = def.label;
        updated = true;
      }
      if (m.input !== def.input) {
        next.input = def.input;
        updated = true;
      }
      if (m.cachedInput !== def.cachedInput) {
        next.cachedInput = def.cachedInput;
        updated = true;
      }
      if (m.output !== def.output) {
        next.output = def.output;
        updated = true;
      }
      if (m.contextWindow !== def.contextWindow) {
        next.contextWindow = def.contextWindow;
        updated = true;
      }
      if (m.supportsThinking !== def.supportsThinking) {
        next.supportsThinking = def.supportsThinking;
        updated = true;
      }
      if (m.supportsTools !== def.supportsTools) {
        next.supportsTools = def.supportsTools;
        updated = true;
      }
      if (m.supportsVision !== def.supportsVision) {
        next.supportsVision = def.supportsVision;
        updated = true;
      }
      if (m.supportsTemperature !== def.supportsTemperature) {
        next.supportsTemperature = def.supportsTemperature;
        updated = true;
      }
      if (m.reasoningEffort !== def.reasoningEffort) {
        next.reasoningEffort = def.reasoningEffort;
        updated = true;
      }
      if (JSON.stringify(m.reasoningEfforts ?? null) !== JSON.stringify(def.reasoningEfforts ?? null)) {
        next.reasoningEfforts = def.reasoningEfforts;
        updated = true;
      }

      if (updated) {
        modelsChanged = true;
        return next;
      }
      return m;
    });

    // 3. Remove built-in models that are no longer in DEFAULT_MODELS
    const currentDefaultIds = new Set(DEFAULT_MODELS.map((dm) => dm.id));
    const nextModels = models.filter((m) => !m.isBuiltIn || currentDefaultIds.has(m.id));
    if (nextModels.length !== models.length) {
      models = nextModels;
      modelsChanged = true;
    }

    // 3.5 Reorder built-in models to match DEFAULT_MODELS order
    const builtinOrder = new Map(DEFAULT_MODELS.map((dm, i) => [dm.id, i]));
    const builtins = models
      .filter((m) => m.isBuiltIn)
      .sort((a, b) => (builtinOrder.get(a.id) ?? 999) - (builtinOrder.get(b.id) ?? 999));
    const customs = models.filter((m) => !m.isBuiltIn);
    const reordered = [...builtins, ...customs];
    if (JSON.stringify(reordered.map((m) => m.id)) !== JSON.stringify(models.map((m) => m.id))) {
      models = reordered;
      modelsChanged = true;
    }

    if (modelsChanged) saveModels(models);

    // 4. Add missing built-in providers (e.g. newly shipped Mistral) and update existing ones (e.g. name changes)
    let providersChanged = false;
    const existingProviderIds = new Set(providers.map((p) => p.id));
    for (const def of DEFAULT_PROVIDERS) {
      if (!existingProviderIds.has(def.id)) {
        providers.push({ ...def, apiKeyEncrypted: '' });
        providersChanged = true;
      }
    }
    for (let i = 0; i < providers.length; i++) {
      const p = providers[i];
      if (!p.isBuiltIn) continue;
      const def = DEFAULT_PROVIDERS.find((dp) => dp.id === p.id);
      if (!def) continue;
      let next = p;
      if (p.name !== def.name) next = { ...next, name: def.name };
      // Sync capability flags so storage from older versions picks up changes
      // (e.g. web search moving from Moonshot to DeepSeek).
      if (p.supportsWebSearch !== def.supportsWebSearch) next = { ...next, supportsWebSearch: def.supportsWebSearch };
      if (next !== p) {
        providers[i] = next;
        providersChanged = true;
      }
    }
    if (providersChanged) saveProviders(providers);
  }

  return { providers, models };
}

const { providers: initialProviders, models: initialModels } = initStore();

export const useProviderStore = create<ProviderState>((set, get) => ({
  providers: initialProviders,
  models: initialModels,

  addProvider: (provider: LlmProvider): void => {
    validateProvider(provider);
    set((state) => {
      const next = [...state.providers, provider];
      saveProviders(next);
      return { providers: next };
    });
  },

  updateProvider: (provider: LlmProvider): void => {
    validateProvider(provider);
    set((state) => {
      const next = state.providers.map((p) => (p.id === provider.id ? provider : p));
      saveProviders(next);
      return { providers: next };
    });
  },

  deleteProvider: (providerId: string): void => {
    set((state) => {
      const removedModels = state.models.filter((m) => m.providerId === providerId);
      const nextProviders = state.providers.filter((p) => p.id !== providerId);
      const nextModels = state.models.filter((m) => m.providerId !== providerId);

      // If the currently persisted selection points to a removed model, fall back.
      const selected = safeGetItem(STORAGE_KEY_SELECTED_MODEL);
      if (selected) {
        const removed = removedModels.some((m) => m.id === selected || m.apiModelId === selected);
        if (removed) {
          if (nextModels.length > 0) {
            safeSetItem(STORAGE_KEY_SELECTED_MODEL, nextModels[0].id);
          } else {
            safeRemoveItem(STORAGE_KEY_SELECTED_MODEL);
          }
        }
      }

      saveProviders(nextProviders);
      saveModels(nextModels);
      return { providers: nextProviders, models: nextModels };
    });
  },

  setProviderKey: (providerId: string, rawKey: string): void => {
    set((state) => {
      const next = state.providers.map((p) => (p.id === providerId ? { ...p, apiKeyEncrypted: rawKey ? encodeApiKey(rawKey) : '' } : p));
      saveProviders(next);
      return { providers: next };
    });
  },

  resetProvider: (providerId: string): void => {
    set((state) => {
      const def = DEFAULT_PROVIDERS.find((dp) => dp.id === providerId);
      if (!def) return state;
      const next = state.providers.map((p) => {
        if (p.id !== providerId) return p;
        return { ...def, apiKeyEncrypted: p.apiKeyEncrypted };
      });
      saveProviders(next);
      return { providers: next };
    });
  },

  addModel: (model: UserChatModel): void => {
    set((state) => {
      const next = [...state.models, model];
      saveModels(next);
      return { models: next };
    });
  },

  updateModel: (model: UserChatModel): void => {
    set((state) => {
      const next = state.models.map((m) => (m.id === model.id ? model : m));
      saveModels(next);
      return { models: next };
    });
  },

  deleteModel: (modelId: string): void => {
    set((state) => {
      const next = state.models.filter((m) => m.id !== modelId);
      saveModels(next);
      return { models: next };
    });
  },

  getProviderById: (id: string): LlmProvider | undefined => {
    return get().providers.find((p) => p.id === id);
  },

  getModelById: (id: string): UserChatModel | undefined => {
    return get().models.find((m) => m.id === id);
  },

  getAvailableModels: (): UserChatModel[] => {
    const { models, providers } = get();
    const available = models.filter((m) => {
      if (!m.enabled) return false;
      const provider = providers.find((p) => p.id === m.providerId);
      if (!provider) return false;
      const hasKey = getApiKey(provider).length > 0;
      return hasKey || providerCanBeUsedWithoutKey(provider);
    });

    return [...available].sort((a, b) => {
      const pA = providers.find((p) => p.id === a.providerId)?.name ?? '';
      const pB = providers.find((p) => p.id === b.providerId)?.name ?? '';

      if (pA !== pB) {
        return pA.localeCompare(pB);
      }
      return a.label.localeCompare(b.label);
    });
  },

  getProviderForModel: (model: UserChatModel): LlmProvider | undefined => {
    return get().providers.find((p) => p.id === model.providerId);
  },

  hasAnyApiKey: (): boolean => {
    return get().getAvailableModels().length > 0;
  },

  hasWebSearchProvider: (): boolean => {
    const { providers } = get();
    return providers.some((p) => p.supportsWebSearch && (getApiKey(p).length > 0 || providerCanBeUsedWithoutKey(p)));
  },
}));
